contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the checker
    function run(address tokenSender, address receiver, uint256 amount) public payable {
        // Precondition: receiver must be nonzero (depositUsdc reverts on zero receiver)
        require(receiver != address(0));
        // amount must be nonzero (depositUsdc reverts on zero amount)
        require(amount != 0);

        // Ensure this contract has enough USDC to transferFrom to c.
        // The test environment won't actually perform ERC20 transfers, but we must call c.depositUsdc.
        // Read before-state
        uint256 beforeRound = c.currentRound();
        uint256 beforeRoundUsdc = c.roundUsdcBalance();
        uint256 beforeUserUsdc = c.usdcBalance(receiver);

        // Call depositUsdc as this contract (msg.sender will be this test contract)
        bool reverted;
        try c.depositUsdc(amount, receiver) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        uint256 afterRound = c.currentRound();
        uint256 afterRoundUsdc = c.roundUsdcBalance();
        uint256 afterUserUsdc = c.usdcBalance(receiver);

        // General invariant to assert:
        // If the call did not revert then:
        //  - currentRound must remain unchanged (depositUsdc doesn't change round)
        //  - roundUsdcBalance increases by exactly amount
        //  - the user's usdcBalance increases by exactly amount unless their previous deposit was from an older round
        //    and already had been converted to unclaimedShares by internal logic; however depositUsdc sets user.round to current and
        //    their user.usdcBalance is previousUserUsdc + amount when user.round == currentRound before call.
        // The following assert encodes the guaranteed parts: non-reversion implies round unchanged and global roundUsdcBalance increased by amount,
        // and user usdcBalance either increases by amount or becomes equal to previous + amount (both same condition) — we conservatively assert
        // that afterUserUsdc >= beforeUserUsdc and increased by at most amount + beforeUserUsdc. This still captures meaningful invariant: a successful deposit always increases or sets the user's usdc balance, and increases the round total by exactly amount.

        assert(
            // if reverted then nothing required; if not reverted enforce properties
            (reverted) || (
                afterRound == beforeRound
                && afterRoundUsdc == beforeRoundUsdc + amount
                && afterUserUsdc >= beforeUserUsdc
                && afterUserUsdc <= beforeUserUsdc + amount
            )
        );
    }

    receive() external payable {}
}

