contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the checker
    function run(uint256 amount, address receiver) public payable {
        // Preconditions to target the non-reverting intended branch
        require(amount != 0);
        require(receiver != address(0));

        // observe before values
        uint256 beforeUser = c.usdcBalance(receiver);
        uint256 beforeRound = c.roundUsdcBalance();

        // attempt the state-changing call and record whether it reverted
        bool reverted;
        try c.depositUsdc(amount, receiver) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after values
        uint256 afterUser = c.usdcBalance(receiver);
        uint256 afterRound = c.roundUsdcBalance();

        // If the call succeeded, both the per-user usdcBalance and the roundUsdcBalance must have increased by >= amount
        assert(reverted || (afterUser >= beforeUser + amount && afterRound >= beforeRound + amount));
    }

